const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const root = '/home/jyarwood/workspace/pi-dish-r12';
require(root + '/test/test-env').applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pi-dish-r12-offline-'));
process.env.HOME = home;
process.env.TMUX_TMPDIR = path.join(home, 'tmux');
process.env.PI_DISH_INDEX_SYNC_BUDGET = '1000';
fs.mkdirSync(process.env.TMUX_TMPDIR);
const dir = path.join(home, '.pi/agent/sessions/project');
fs.mkdirSync(dir, { recursive: true });
const id = '2026-09-16T00-00-00-r12-offline';
const source = '# Offline highlighting\n\n```javascript\nconst answer = 42;\nconsole.log(answer);\n```\n\n```python\ndef greet(name):\n    return f"Hello {name}"\n```';
fs.writeFileSync(path.join(dir, id + '.jsonl'), [
  {type:'session',cwd:home,timestamp:'2026-09-16T00:00:00.000Z'},
  {type:'message',message:{role:'user',content:'R12 offline common-language rendering'}},
  {type:'message',id:'offline-answer',message:{role:'assistant',content:[{type:'text',text:source}],timestamp:Date.parse('2026-09-16T00:00:01.000Z')}}
].map(x=>JSON.stringify(x)).join('\n')+'\n');
const server = require(root + '/server.js');
server.on('listening', () => {
  const result = {base:'http://127.0.0.1:'+server.address().port,home,id};
  fs.writeFileSync('/tmp/r12-runtime.json',JSON.stringify(result));
  console.log('R12_READY ' + JSON.stringify(result));
});
process.on('SIGTERM', () => {
  server.close(() => { fs.rmSync(home,{recursive:true,force:true}); process.exit(0); });
  server.closeAllConnections();
});

