const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const root = '/home/jyarwood/workspace/pi-dish-r12';
const baseline = execFileSync('git',['show','dc4ae84568fda976cfb136082b1dda405ccf54d8:public/vendor/highlight.js'],{cwd:root,encoding:'utf8'});
const current = fs.readFileSync(root+'/public/vendor/highlight.js','utf8');
function load(source) { const context = {window:{},console:{log(){},warn(){},error(){}}};vm.runInNewContext(source,context);return context.window.hljs; }
const old = load(baseline), next = load(current);
assert.deepEqual(Object.keys(next).sort(),Object.keys(old).sort());
assert.deepEqual(Array.from(next.listLanguages()),Array.from(old.listLanguages()));
assert.equal(next.versionString,old.versionString);
assert.equal(next.default,next);assert.equal(next.HighlightJS,next);
const samples = ['const answer = 42; console.log(answer);','def greet(name):\n    return f"Hello {name}"','<div class="x">&amp;</div>','fn main() { println!("offline"); }','SELECT * FROM users WHERE id = 1;','{"name":"offline","value":42}','#!/bin/bash\necho "$HOME"','<script>alert("inert")</script>'];
let cases = 0;
for (const language of old.listLanguages()) for (const code of samples) {
  const a=old.highlight(code,{language}),b=next.highlight(code,{language});
  for (const field of ['value','language','relevance','illegal','code']) assert.equal(b[field],a[field]);
  cases++;
}
for (const code of samples) {
 const a=old.highlightAuto(code),b=next.highlightAuto(code);
 for (const field of ['value','language','relevance','illegal']) assert.equal(b[field],a[field]);
 cases++;
}
for (const runtime of [old,next]) assert.throws(()=>runtime.highlight('x',{language:'missing-r12-language'}),/Unknown language/);
const license=fs.readFileSync(root+'/node_modules/highlight.js/LICENSE','utf8').trim();
assert.ok(current.includes(license));
assert.ok(baseline.includes(license));
assert.equal(/__mods|__cache|__req\(/.test(current),false);
const result={languages:Array.from(next.listLanguages()),api:Object.keys(next).sort(),version:next.versionString,cases,unknownLanguageErrorPreserved:true,licensePreserved:true,manualLoaderAbsent:true,baselineBytes:Buffer.byteLength(baseline),currentBytes:Buffer.byteLength(current)};
fs.writeFileSync('/tmp/r12-parity-result.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result,null,2));
